const entry = msg.payload;

msg.payload = {
    id:        entry.id,
    text:      entry.text             || "",
    timestamp: entry.timeCreated,
    author:    entry.loggedByFullName || "",
    labels:    entry.labels           || [],
};

return msg;

const entry = msg.payload;

const text = entry.content || "";

msg.payload = {
    id:        entry.id,
    text:      text,
    timestamp: new Date(entry.createdAt).getTime(),
    author:    entry.username || "",
    files:     [],
    labels:    []
};

return msg;

const c = msg.payload;
const reg = c.registration || {};
const g   = c.global || {};
const parse = global.get("utils").parse_cim_timestamp;

msg.payload = {
    id:        String(g.case_id),
    text:      striptags(reg.subject || "") + ": " + striptags(reg.description || ""),
    timestamp: parse(g.case_created),
    author:    g.case_created_by || "",
    files:     [],
    labels:    []
};

if (g.latitude && g.longitude) {
    msg.metadata.geo = {
        lat:  parseFloat(g.latitude),
        lng:  parseFloat(g.longitude),
        name: g.location || ("Case " + (g.display_id || g.case_id))
    };
}

return msg;
